def lol_champion_leader_board(region, champion, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "lol-champion-leader-board"
    used_credential = None

    # --- helpers ---
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.utcfromtimestamp(v)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _coalesce(v, d="-"):
        return v if v is not None else d

    def _record_call(status, error_code=None):
        # Optional observable dynamics: if request log exists, append.
        # Schema didn't declare it; implement only if present.
        fname_candidates = ["request_logs.json", "usage_logs.json", "api_requests.json", "audit_log.json", "audit_logs.json"]
        existing = None
        for fn in fname_candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                existing = fn
                break
        if not existing:
            return
        logs = _load(existing)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": used_credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save(existing, logs)

    # --- validate inputs ---
    allowed_region = {"KR","BR","EUNE","EUW","LAN","LAS","NA","OCE","RU","TR","JP","PH","SG","TH","TW","VN","ME","SEA"}
    if not isinstance(region, str) or region not in allowed_region:
        _record_call("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid or missing region.", field="region")
    if not isinstance(champion, str) or not champion:
        _record_call("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid or missing champion.", field="champion")
    # Champion enum list is large; trust caller enum list but still require catalog validation.
    # Enforce "All champion IDs accepted must correspond to an active game_catalog row".
    game_catalog = _load("game_catalog.json")
    champ_row = None
    for r in game_catalog:
        if r.get("game") == "LOL" and r.get("entity_type") == "LOL_CHAMPION" and r.get("external_key") == champion:
            champ_row = r
            break
    if not champ_row:
        _record_call("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Champion not found in catalog.", champion=champion)
    if champ_row.get("status") != "active":
        _record_call("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Champion is not active in catalog.", champion=champion)

    # --- find latest snapshot ---
    snapshots = _load("meta_snapshots.json")
    dims = {
        "snapshot_type": "LOL_CHAMPION_LEADERBOARD",
        "region": region,
        "champion_external_key": champion,
    }

    def _dims_match(s):
        if s.get("snapshot_type") != dims["snapshot_type"]:
            return False
        if s.get("region") != dims["region"]:
            return False
        if s.get("champion_external_key") != dims["champion_external_key"]:
            return False
        # Must match all other dims as null/absent
        for k in ["lang","game_mode","position","tft_champion_external_key","tft_item_external_key","valorant_map_external_key","esports_league_short_name","format"]:
            if s.get(k) is not None:
                return False
        return True

    active = []
    superseded = []
    for s in snapshots:
        if not _dims_match(s):
            continue
        st = s.get("status")
        if st == "active":
            active.append(s)
        elif st == "superseded":
            superseded.append(s)

    def _eff_from(s):
        dt = _parse_dt(s.get("effective_from")) or _parse_dt(s.get("created_at")) or datetime.datetime.min
        return dt

    chosen = None
    # Prefer active with effective_to NULL (current), otherwise latest active
    if active:
        active_sorted = sorted(active, key=_eff_from, reverse=True)
        # Prefer those with effective_to is None (should be at most one)
        current = [s for s in active_sorted if s.get("effective_to") is None]
        chosen = current[0] if current else active_sorted[0]
    else:
        # Fallback to most recent superseded within staleness window
        # Use 14 days as a reasonable allowed window for offline snapshot fallback.
        window = datetime.timedelta(days=14)
        now = datetime.datetime.utcnow()
        superseded_sorted = sorted(superseded, key=_eff_from, reverse=True)
        for s in superseded_sorted:
            ef = _eff_from(s)
            if ef != datetime.datetime.min and (now - ef) <= window:
                chosen = s
                break

    if not chosen:
        _record_call("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No leaderboard snapshot available for the requested region/champion.", region=region, champion=champion)

    resp = {
        "snapshot": chosen,
        "region": region,
        "champion": champion,
        "catalog": {
            "id": champ_row.get("id"),
            "external_key": champ_row.get("external_key"),
            "display_name_default": champ_row.get("display_name_default"),
            "localized_names": champ_row.get("localized_names"),
            "metadata": champ_row.get("metadata"),
        },
    }
    _record_call("ok")
    return resp

