        _record_call("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid or missing champion.", field="champion")

    # Enforce champion exists and is active in catalog
    game_catalog = _load("game_catalog.json")
    champ_row = None
    for r in game_catalog:
        if r.get("game") == "LOL" and r.get("entity_type") == "LOL_CHAMPION" and r.get("external_key") == champion:
            champ_row = r
            break
    if not champ_row:
        _record_call("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Champion not found in catalog.", champion=champion)
    if champ_row.get("status") != "active":
        _record_call("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Champion is not active in catalog.", champion=champion)

    # --- find latest snapshot ---
    snapshots = _load("meta_snapshots.json")

    def _dims_match(s):
        if s.get("snapshot_type") != "LOL_CHAMPION_ANALYSIS":
            return False
        if s.get("game") not in (None, "LOL"):
            return False
        if s.get("game_mode") != game_mode:
            return False
        if s.get("position") != position:
            return False
        if s.get("lang") != lang:
            return False
        if s.get("champion_external_key") != champion:
            return False
        # No region dimension for this tool per schema (region should be null)
        if s.get("region") is not None:
            return False
        # Must not carry unrelated dims
        for k in ["tft_champion_external_key","tft_item_external_key","valorant_map_external_key","esports_league_short_name","format"]:
            if s.get(k) is not None:
                return False
        return True

    def _eff_from(s):
        return _parse_dt(s.get("effective_from")) or _parse_dt(s.get("created_at")) or datetime.datetime.min

    active = []
    superseded = []
    for s in snapshots:
        if not _dims_match(s):
            continue
        if s.get("status") == "active":
            active.append(s)
        elif s.get("status") == "superseded":
            superseded.append(s)

    chosen = None
    if active:
        active_sorted = sorted(active, key=_eff_from, reverse=True)
        current = [s for s in active_sorted if s.get("effective_to") is None]
        chosen = current[0] if current else active_sorted[0]
    else:
        window = datetime.timedelta(days=14)
        now = datetime.datetime.utcnow()
        superseded_sorted = sorted(superseded, key=_eff_from, reverse=True)
        for s in superseded_sorted:
            ef = _eff_from(s)
            if ef != datetime.datetime.min and (now - ef) <= window:
                chosen = s
                break

    if not chosen:
        _record_call("error", "NOT_FOUND")
        return _err(
            "NOT_FOUND",
            "No champion analysis snapshot available for the requested dimensions.",
            game_mode=game_mode, champion=champion, position=position, lang=lang
        )

    resp = {
        "snapshot": chosen,
        "game_mode": game_mode,
        "champion": champion,
        "position": position,
        "lang": lang,
        "catalog": {
            "id": champ_row.get("id"),
            "external_key": champ_row.get("external_key"),
            "display_name_default": champ_row.get("display_name_default"),
            "localized_names": champ_row.get("localized_names"),
            "metadata": champ_row.get("metadata"),
        },
    }
    _record_call("ok")
    return resp

