    }

    if not isinstance(champion, str) or champion not in champion_enum:
        _log("error", "VALIDATION_ERROR", "Invalid or missing champion")
        return _err("VALIDATION_ERROR", "Invalid or missing champion", field="champion")
    if not isinstance(lang, str) or lang not in lang_enum:
        _log("error", "VALIDATION_ERROR", "Invalid or missing lang")
        return _err("VALIDATION_ERROR", "Invalid or missing lang", field="lang")

    # Enforce "champion IDs accepted by tools must correspond to an active game_catalog row"
    catalog = _load("game_catalog.json")
    cat_ok = False
    for r in catalog if isinstance(catalog, list) else []:
        if (
            isinstance(r, dict)
            and r.get("game") == "LOL"
            and r.get("entity_type") == "LOL_CHAMPION"
            and r.get("external_key") == champion
            and r.get("status") == "active"
        ):
            cat_ok = True
            break
    if not cat_ok:
        _log("error", "NOT_FOUND", "Champion not found in active catalog")
        return _err("NOT_FOUND", "Champion not found", champion=champion)

    snapshots = _load("meta_snapshots.json")
    if not isinstance(snapshots, list):
        _log("error", "NOT_FOUND", "No snapshot store available")
        return _err("NOT_FOUND", "Champion meta snapshot is unavailable")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Lookup: latest active matching dimensions
    dims = {
        "snapshot_type": "LOL_CHAMPION_META_DATA",
        "game": "LOL",
        "champion_external_key": champion,
        "lang": lang,
        "region": None,
        "game_mode": None,
        "position": None,
        "format": None,
    }

    def _match(row):
        if not isinstance(row, dict):
            return False
        if row.get("snapshot_type") != dims["snapshot_type"]:
            return False
        if row.get("game") != dims["game"]:
            return False
        if row.get("champion_external_key") != dims["champion_external_key"]:
            return False
        if row.get("lang") != dims["lang"]:
            return False
        # must be null for unspecified dims for this tool
        for k in ("region", "game_mode", "position", "tft_champion_external_key", "tft_item_external_key",
                  "valorant_map_external_key", "esports_league_short_name", "format"):
            if row.get(k) is not None:
                return False
        if row.get("effective_to") is not None:
            # active snapshots must be current (effective_to null) by constraint intent
            # allow but deprioritize; selection prefers current
            pass
        return True

    candidates = [r for r in snapshots if _match(r)]
    active = [r for r in candidates if r.get("status") == "active" and r.get("effective_to") is None]
    active2 = [r for r in candidates if r.get("status") == "active"]  # fallback if effective_to was set incorrectly

    def _sort_key(r):
        ef = _parse_dt(r.get("effective_from")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        ca = _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (ef, ca)

    chosen = None
    if active:
        chosen = sorted(active, key=_sort_key, reverse=True)[0]
    elif active2:
        chosen = sorted(active2, key=_sort_key, reverse=True)[0]
    else:
        # fallback: most recent superseded within staleness window (e.g., 30 days)
        superseded = [r for r in candidates if r.get("status") == "superseded"]
        if superseded:
            superseded_sorted = sorted(superseded, key=_sort_key, reverse=True)
            most_recent = superseded_sorted[0]
            ef = _parse_dt(most_recent.get("effective_from"))
            # If can't parse, allow it as best-effort.
            staleness_ok = True
            if ef is not None:
                staleness_ok = (datetime.datetime.now(datetime.timezone.utc) - ef) <= datetime.timedelta(days=30)
            if staleness_ok:
                chosen = most_recent

    if not chosen or not isinstance(chosen.get("payload"), dict):
        _log("error", "NOT_FOUND", "Champion meta snapshot is unavailable")
        return _err("NOT_FOUND", "Champion meta snapshot is unavailable", champion=champion, lang=lang)

    _log("ok")
    return {
        "data": chosen.get("payload"),
        "meta": {
            "snapshot_id": chosen.get("id"),
            "snapshot_type": chosen.get("snapshot_type"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "status": chosen.get("status"),
            "lang": lang,
            "champion": champion,
        },
    }

def lol_champion_skin_sale(lang, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Simple rate limit if request_logs exists: 60 req/min per endpoint (ambient auth)
    def _rate_limit_ok():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "lol-champion-skin-sale":
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1] + "+00:00") if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        return cnt < 60

    def _log(status, code=None, message=None, extra=None):
        try:
            logs = _load("request_logs.json")
            if isinstance(logs, list):
                row = {
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                    "service": "OP.GG",
                    "endpoint": "lol-champion-skin-sale",
                    "status": status,
                    "error_code": code,
                    "error_message": message,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now,
                }
                if isinstance(extra, dict):
                    row.update(extra)
                logs.append(row)
                _save("request_logs.json", logs)
        except Exception:
            return

    lang_enum = {
        "ar_AE", "cs_CZ", "de_DE", "el_GR", "en_US", "en_AU", "en_GB", "en_PH", "en_SG", "es_AR", "es_ES", "es_MX",
        "fr_FR", "hu_HU", "it_IT", "ja_JP", "ko_KR", "pl_PL", "pt_BR", "ro_RO", "ru_RU", "th_TH", "tr_TR", "vi_VN",
        "zh_CN", "zh_MY", "zh_TW"
    }
    if not isinstance(lang, str) or lang not in lang_enum:
        _log("error", "VALIDATION_ERROR", "Invalid or missing lang")
        return _err("VALIDATION_ERROR", "Invalid or missing lang", field="lang")

    if not _rate_limit_ok():
        _log("error", "RATE_LIMIT", "Too many requests")
        return _err("RATE_LIMIT", "Too many requests")

    snapshots = _load("meta_snapshots.json")
    if not isinstance(snapshots, list):
        _log("error", "NOT_FOUND", "No snapshot store available")
        return _err("NOT_FOUND", "No active sale catalog is available for the requested language", lang=lang)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Tool dimensions: snapshot_type='LOL_CHAMPION_SKIN_SALE', game='LOL', lang required, others null
    def _match(row):
        if not isinstance(row, dict):
            return False
        if row.get("snapshot_type") != "LOL_CHAMPION_SKIN_SALE":
            return False
        if row.get("game") != "LOL":
            return False
        if row.get("lang") != lang:
            return False
        for k in ("region", "game_mode", "position", "champion_external_key", "tft_champion_external_key",
                  "tft_item_external_key", "valorant_map_external_key", "esports_league_short_name", "format"):
            if row.get(k) is not None:
                return False
        return True

    candidates = [r for r in snapshots if _match(r)]
    active = [r for r in candidates if r.get("status") == "active" and r.get("effective_to") is None]
    active2 = [r for r in candidates if r.get("status") == "active"]

    def _sort_key(r):
        ef = _parse_dt(r.get("effective_from")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        ca = _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (ef, ca)

    chosen = None
    if active:
        chosen = sorted(active, key=_sort_key, reverse=True)[0]
    elif active2:
        chosen = sorted(active2, key=_sort_key, reverse=True)[0]
    else:
        superseded = [r for r in candidates if r.get("status") == "superseded"]
        if superseded:
            superseded_sorted = sorted(superseded, key=_sort_key, reverse=True)
            most_recent = superseded_sorted[0]
            ef = _parse_dt(most_recent.get("effective_from"))
            staleness_ok = True
            if ef is not None:
                staleness_ok = (datetime.datetime.now(datetime.timezone.utc) - ef) <= datetime.timedelta(days=30)
            if staleness_ok:
                chosen = most_recent

    if not chosen:
        _log("error", "NOT_FOUND", "No active sale catalog is available for the requested language")
        return _err("NOT_FOUND", "No active sale catalog is available for the requested language", lang=lang)

    payload = chosen.get("payload")
    if not isinstance(payload, (list, dict)):
        _log("error", "NOT_FOUND", "No active sale catalog is available for the requested language")
        return _err("NOT_FOUND", "No active sale catalog is available for the requested language", lang=lang)

    _log("ok")
    return {
        "data": payload,
        "meta": {
            "snapshot_id": chosen.get("id"),
            "snapshot_type": chosen.get("snapshot_type"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "status": chosen.get("status"),
            "lang": lang,
        },
    }

def lol_summoner_search(game_name, tag_line, region, lang, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Validation ---
    if not isinstance(game_name, str) or not game_name.strip():
        return _err("VALIDATION_ERROR", "game_name is required and must be a non-empty string.", field="game_name")
    if not isinstance(tag_line, str) or not tag_line.strip():
        return _err("VALIDATION_ERROR", "tag_line is required and must be a non-empty string.", field="tag_line")
    if not isinstance(region, str):
        return _err("VALIDATION_ERROR", "region must be a string.", field="region")
    if not isinstance(lang, str):
        return _err("VALIDATION_ERROR", "lang must be a string.", field="lang")

    allowed_regions = {"KR","BR","EUNE","EUW","LAN","LAS","NA","OCE","RU","TR","JP","PH","SG","TH","TW","VN","ME","SEA"}
    if region not in allowed_regions:
        return _err("VALIDATION_ERROR", "Invalid region.", field="region", allowed=sorted(allowed_regions))
    allowed_langs = {"ar_AE","cs_CZ","de_DE","el_GR","en_US","en_AU","en_GB","en_PH","en_SG","es_AR","es_ES","es_MX","fr_FR","hu_HU","it_IT","ja_JP","ko_KR","pl_PL","pt_BR","ro_RO","ru_RU","th_TH","tr_TR","vi_VN","zh_CN","zh_MY","zh_TW"}
    if lang not in allowed_langs:
        return _err("VALIDATION_ERROR", "Invalid lang.", field="lang", allowed=sorted(allowed_langs))

    # Basic Riot ID hygiene (not overly strict)
    if len(game_name.strip()) > 32:
        return _err("VALIDATION_ERROR", "game_name is too long.", field="game_name", max_length=32)
    if len(tag_line.strip()) > 16:
        return _err("VALIDATION_ERROR", "tag_line is too long.", field="tag_line", max_length=16)

    def _norm_riot_id(gn, tl):
        gn2 = re.sub(r"\s+", " ", gn.strip()).lower()
        tl2 = re.sub(r"\s+", " ", tl.strip()).lower()
        return f"{gn2}#{tl2}"

    normalized = _norm_riot_id(game_name, tag_line)

    # --- Load datastore ---
    players = _load("players.json")
    matches = _load("player_matches.json")

    # --- Find player cache row ---
    # unique(product, region, normalized_riot_id)
    player = None
    for p in players:
        if p.get("product") == "LOL" and p.get("region") == region and p.get("normalized_riot_id") == normalized:
            player = p
            break

    if not player:
        return _err("NOT_FOUND", "No cached summoner profile found for the provided Riot ID in this region. Run renewal first.", normalized_riot_id=normalized, region=region)

    # Must read from cache; if not found/disabled, treat as not found for this tool (client should renew)
    if player.get("status") != "active":
        # If explicitly not_found/disabled, return NOT_FOUND with hint to renew
        return _err("NOT_FOUND", "Summoner cache is not available (status is not active). Run renewal first.", status=player.get("status"), normalized_riot_id=normalized, region=region)

    # Gather match history (latest-first), return unpaged block as stored.
    pid = player.get("id")
    player_match_rows = [m for m in matches if m.get("player_id") == pid and m.get("product") == "LOL" and m.get("status") == "active"]
    # Sort by played_at desc, then ingested_at desc
    def _dt_key(v):
        if not v:
            return ""
        return v
    player_match_rows.sort(key=lambda r: (_dt_key(r.get("played_at")), _dt_key(r.get("ingested_at"))), reverse=True)

    latency_ms = int((time.time() - t0) * 1000)

    # NOTE: No request/usage log collection present in schema; nothing to persist for call dynamics.

    return {
        "summoner": {
            "id": player.get("id"),
            "product": player.get("product"),
            "region": player.get("region"),
            "game_name": player.get("game_name"),
            "tag_line": player.get("tag_line"),
            "normalized_riot_id": player.get("normalized_riot_id"),
            "puuid": player.get("puuid"),
            "status": player.get("status"),
            "last_renewed_at": player.get("last_renewed_at"),
            "profile_payload": player.get("profile_payload"),
            "created_at": player.get("created_at"),
            "updated_at": player.get("updated_at"),
        },
        "matches": [
            {
                "id": m.get("id"),
                "external_match_id": m.get("external_match_id"),
                "played_at": m.get("played_at"),
                "queue_or_mode": m.get("queue_or_mode"),
                "region": m.get("region"),
                "summary_payload": m.get("summary_payload"),
                "ingested_at": m.get("ingested_at"),
                "status": m.get("status"),
                "created_at": m.get("created_at"),
                "updated_at": m.get("updated_at"),
            }
            for m in player_match_rows
        ],
        "meta": {
            "lang": lang,
            "returned_match_count": len(player_match_rows),
            "latency_ms": latency_ms,
            "timestamp": now,
            "cache_only": True,
        },
    }

