    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Validation ---
    if not isinstance(lang, str):
        return _err("VALIDATION_ERROR", "lang must be a string.", field="lang")
    allowed_langs = {"ar_AE","cs_CZ","de_DE","el_GR","en_US","en_AU","en_GB","en_PH","en_SG","es_AR","es_ES","es_MX","fr_FR","hu_HU","it_IT","ja_JP","ko_KR","pl_PL","pt_BR","ro_RO","ru_RU","th_TH","tr_TR","vi_VN","zh_CN","zh_MY","zh_TW"}
    if lang not in allowed_langs:
        return _err("VALIDATION_ERROR", "Invalid lang.", field="lang", allowed=sorted(allowed_langs))

    if format is None:
        format = "csv"
    if not isinstance(format, str):
        return _err("VALIDATION_ERROR", "format must be a string.", field="format")
    allowed_formats = {"csv", "json_zip"}
    if format not in allowed_formats:
        return _err("VALIDATION_ERROR", "Invalid format.", field="format", allowed=sorted(allowed_formats))

    snapshots = _load("meta_snapshots.json")

    snapshot_type = "LOL_CHAMPION_POSITIONS_DATA"

    # Find active snapshot first for (snapshot_type, lang, format)
    def _match_dims(r):
        return (
            r.get("snapshot_type") == snapshot_type and
            r.get("game") == "LOL" and
            r.get("lang") == lang and
            (r.get("format") or None) == (format or None) and
            r.get("region") is None and
            r.get("game_mode") is None and
            r.get("position") is None and
            r.get("champion_external_key") is None and
            r.get("tft_champion_external_key") is None and
            r.get("tft_item_external_key") is None and
            r.get("valorant_map_external_key") is None and
            r.get("esports_league_short_name") is None
        )

    candidates = [r for r in snapshots if _match_dims(r)]

    def _iso(v):
        return v or ""

    active = [r for r in candidates if r.get("status") == "active" and r.get("effective_to") is None]
    active.sort(key=lambda r: (_iso(r.get("effective_from")), _iso(r.get("created_at"))), reverse=True)

    chosen = active[0] if active else None

    # Fallback to most recent superseded within staleness window (allowed by business rule).
    # Use 30 days as the staleness window (service-side policy).
    if chosen is None:
        superseded = [r for r in candidates if r.get("status") == "superseded"]
        superseded.sort(key=lambda r: (_iso(r.get("effective_from")), _iso(r.get("updated_at"))), reverse=True)
        if superseded:
            latest = superseded[0]
            # Determine staleness using effective_to if present else updated_at
            ref = latest.get("effective_to") or latest.get("updated_at") or latest.get("created_at")
            stale_ok = True
            if ref:
                try:
                    # parse basic Z or naive isoformat
                    dt = None
                    if isinstance(ref, str):
                        s = ref[:-1] if ref.endswith("Z") else ref
                        dt = datetime.datetime.fromisoformat(s)
                    else:
                        dt = None
                    if dt is not None:
                        age_days = (datetime.datetime.utcnow() - dt).days
                        stale_ok = age_days <= 30
                except Exception:
                    stale_ok = True
            if stale_ok:
                chosen = latest

    if chosen is None:
        # Meta read tools: if none exists, return NOT_FOUND? Contract doesn't specify.
        # Realistic behavior: indicate not found for this meta dataset.
        return _err("NOT_FOUND", "No meta snapshot available for champion positions data with the specified dimensions.", snapshot_type=snapshot_type, lang=lang, format=format)

    latency_ms = int((time.time() - t0) * 1000)

    # NOTE: No request/usage log collection present in schema; nothing to persist for call dynamics.

    return {
        "snapshot": {
