            "updated_at": chosen.get("updated_at"),
        },
        "data": chosen.get("payload"),
        "meta": {
            "requested_lang": lang,
            "requested_format": format,
            "served_status": chosen.get("status"),
            "latency_ms": latency_ms,
            "timestamp": now,
        }
    }

def lol_summoner_game_history(game_name, tag_line, region, lang, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / quota ----
    def _log(status, error=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - start) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "OP.GG",
            "endpoint": "lol-summoner-game-history",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms,
            "error": error,
            "meta": extra or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        # Simple, deterministic limits (offline emulation):
        # - rate: 120 requests / 60 seconds
        # - daily quota: 5000 requests / 24 hours
        t_now = datetime.datetime.utcnow()
        def _parse(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    return datetime.datetime.fromisoformat(ts[:-1])
                if isinstance(ts, str):
                    return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None
            return None

        last_min = 0
        last_day = 0
        for r in logs:
            ts = _parse(r.get("timestamp"))
            if not ts:
                continue
            dt = (t_now - ts).total_seconds()
            if 0 <= dt <= 60:
                last_min += 1
            if 0 <= dt <= 86400:
                last_day += 1
        if last_min >= 120:
            return _err("RATE_LIMIT", "Too many requests. Please try again later.", retry_after_seconds=60)
        if last_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", reset_after_seconds=86400)
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", error=lim_err["error"])
        return lim_err

    # ---- validation ----
    LOL_REGIONS = {"KR","BR","EUNE","EUW","LAN","LAS","NA","OCE","RU","TR","JP","PH","SG","TH","TW","VN","ME","SEA"}
    LANGS = {"ar_AE","cs_CZ","de_DE","el_GR","en_US","en_AU","en_GB","en_PH","en_SG","es_AR","es_ES","es_MX","fr_FR","hu_HU","it_IT","ja_JP","ko_KR","pl_PL","pt_BR","ro_RO","ru_RU","th_TH","tr_TR","vi_VN","zh_CN","zh_MY","zh_TW"}

    if not isinstance(game_name, str) or not game_name.strip():
        e = _err("VALIDATION_ERROR", "game_name must be a non-empty string.")
        _log("error", error=e["error"])
        return e
    if not isinstance(tag_line, str) or not tag_line.strip():
        e = _err("VALIDATION_ERROR", "tag_line must be a non-empty string.")
        _log("error", error=e["error"])
        return e
    if not isinstance(region, str) or region not in LOL_REGIONS:
        e = _err("VALIDATION_ERROR", "region is invalid for LoL.", allowed=sorted(LOL_REGIONS))
        _log("error", error=e["error"])
        return e
    if not isinstance(lang, str) or lang not in LANGS:
        e = _err("VALIDATION_ERROR", "lang is invalid.", allowed=sorted(LANGS))
        _log("error", error=e["error"])
        return e

    def _norm_riot_id(gn, tl):
        gn2 = " ".join(gn.strip().split())
        tl2 = " ".join(tl.strip().split())
        return (gn2 + "#" + tl2).strip().lower()

    norm = _norm_riot_id(game_name, tag_line)

    players = _load("players.json")
    if not isinstance(players, list):
        players = []
    matches = _load("player_matches.json")
    if not isinstance(matches, list):
        matches = []

    # Find cached player
    player = None
    for p in players:
        if p.get("product") == "LOL" and p.get("region") == region and p.get("normalized_riot_id") == norm:
            player = p
            break

    # If no player row exists: read returns empty set (not an error), but instruct renewal.
    if not player:
        resp = {
            "summoner": None,
            "matches": [],
            "meta": {
                "total": 0,
                "has_more": False,
                "next_cursor": None,
                "cache_status": "missing",
                "action_required": "Run lol-summoner-renewal first to populate cache."
            }
        }
        _log("ok", extra={"cache_status": "missing", "region": region, "lang": lang})
        return resp

    # If player is not_found and stale/never renewed: instruct renewal again (tool contract says renewal first).
    last_renewed_at = player.get("last_renewed_at")
    stale = True
    if isinstance(last_renewed_at, str):
        try:
            ts = datetime.datetime.fromisoformat(last_renewed_at[:-1]) if last_renewed_at.endswith("Z") else datetime.datetime.fromisoformat(last_renewed_at)
            stale = (datetime.datetime.utcnow() - ts).total_seconds() > 6 * 3600  # 6h staleness window for cache
        except Exception:
            stale = True

    if player.get("status") == "not_found" and (not last_renewed_at or stale):
        resp = {
            "summoner": {
                "id": player.get("id"),
                "product": player.get("product"),
                "region": player.get("region"),
                "game_name": player.get("game_name"),
                "tag_line": player.get("tag_line"),
                "status": player.get("status"),
                "last_renewed_at": player.get("last_renewed_at"),
                "profile_payload": player.get("profile_payload"),
            },
            "matches": [],
            "meta": {
                "total": 0,
                "has_more": False,
                "next_cursor": None,
                "cache_status": "stale_not_found",
                "action_required": "Run lol-summoner-renewal again (cache indicates not_found and is stale)."
            }
        }
        _log("ok", extra={"cache_status": "stale_not_found", "player_id": player.get("id")})
        return resp

    # Return recent matches from cache
    pid = player.get("id")
    pm = [m for m in matches if m.get("player_id") == pid and m.get("product") == "LOL" and m.get("status") == "active"]
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    pm.sort(key=lambda r: (_parse_dt(r.get("played_at")) or datetime.datetime.min), reverse=True)

    # Envelope: provide matches (compact) plus metadata.
    out_matches = []
    for m in pm[:50]:
        out_matches.append({
            "id": m.get("id"),
            "external_match_id": m.get("external_match_id"),
            "played_at": m.get("played_at"),
            "queue_or_mode": m.get("queue_or_mode"),
            "summary_payload": m.get("summary_payload"),
        })

    resp = {
        "summoner": {
            "id": player.get("id"),
            "product": player.get("product"),
            "region": player.get("region"),
            "game_name": player.get("game_name"),
            "tag_line": player.get("tag_line"),
            "status": player.get("status"),
            "last_renewed_at": player.get("last_renewed_at"),
            "profile_payload": player.get("profile_payload"),
        },
        "matches": out_matches,
        "meta": {
            "total": len(pm),
            "returned": len(out_matches),
            "has_more": len(pm) > len(out_matches),
            "next_cursor": None,
            "cache_status": "ok" if player.get("status") == "active" else player.get("status"),
            "note": "This endpoint serves cached OP.GG data. Run lol-summoner-renewal to refresh.",
        }
    }
    _log("ok", extra={"player_id": player.get("id"), "total": len(pm)})
    return resp

