        "zh_CN","zh_MY","zh_TW"
    }
    ve = _validate_enum(lang, allowed_lang, "lang")
    if ve:
        _log("error", error=ve["error"])
        return ve

    snapshots = _load("meta_snapshots.json")

    def _dims_match(s):
        return (
            s.get("game") == "LOL"
            and s.get("snapshot_type") == "LOL_BRAWL_CHAMPION_TIER_RANK"
            and s.get("lang") == lang
            and (s.get("region") is None)
            and (s.get("game_mode") is None)
            and (s.get("position") is None)
