            and (s.get("tft_champion_external_key") is None)
            and (s.get("tft_item_external_key") is None)
            and (s.get("valorant_map_external_key") is None)
            and (s.get("esports_league_short_name") is None)
        )

    def _parse_dt(x):
        if not isinstance(x, str) or not x:
            return None
        try:
            if x.endswith("Z"):
                return datetime.datetime.fromisoformat(x[:-1])
            return datetime.datetime.fromisoformat(x)
        except ValueError:
            return None

    candidates_active = [s for s in snapshots if _dims_match(s) and s.get("status") == "active" and s.get("effective_to") is None]
    chosen = None
    if candidates_active:
        # pick latest effective_from
        candidates_active.sort(key=lambda r: (_parse_dt(r.get("effective_from")) or datetime.datetime.min), reverse=True)
        chosen = candidates_active[0]
    else:
        # fallback to most recent superseded within staleness window (14 days)
        window = datetime.timedelta(days=14)
        now = datetime.datetime.utcnow()
        superseded = [s for s in snapshots if _dims_match(s) and s.get("status") == "superseded"]
        # choose by effective_to or updated_at, but must be recent
        def _recency(r):
            return (_parse_dt(r.get("effective_to")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("effective_from")) or datetime.datetime.min)
        superseded.sort(key=_recency, reverse=True)
        for s in superseded:
            dt = _recency(s)
            if dt is not None and (now - dt) <= window:
                chosen = s
                break

    if not chosen:
