    # (Best effort: only enforce when keys are present; do not fabricate failures on unknown payload schema.)
    payload = chosen.get("payload")
    if isinstance(payload, dict):
        # common patterns: payload["data"] list, payload["champions"] list, payload["tiers"] list
        possible_lists = []
        for k in ("data", "champions", "tiers", "list", "items"):
            v = payload.get(k)
            if isinstance(v, list):
                possible_lists.append(v)
        champion_keys = set()
        for lst in possible_lists:
            for it in lst:
                if isinstance(it, dict):
                    for ck in ("champion_external_key", "championKey", "champion_id", "championId", "key"):
                        v = it.get(ck)
                        if isinstance(v, str) and v:
                            champion_keys.add(v)
                            break
        if champion_keys:
            catalog = _load("game_catalog.json")
            active = set(
                r.get("external_key")
                for r in catalog
                if r.get("game") == "LOL" and r.get("entity_type") == "LOL_CHAMPION" and r.get("status") == "active"
            )
            missing = sorted([k for k in champion_keys if k not in active])
            if missing:
                err = _err(
                    "CONFLICT",
                    "Snapshot payload references champions not present as active in game_catalog",
                    missing_external_keys=missing[:50],
                    missing_count=len(missing),
                )
                _log("error", error=err["error"])
                return err

    _log("ok", meta={"snapshot_id": chosen.get("id")})
    return {
        "snapshot": {
            "id": chosen.get("id"),
            "game": chosen.get("game"),
            "snapshot_type": chosen.get("snapshot_type"),
            "lang": chosen.get("lang"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "status": chosen.get("status"),
            "source_patch": chosen.get("source_patch"),
            "updated_at": chosen.get("updated_at"),
        },
        "data": payload,
        "meta": {"lang": lang, "snapshot_type": "LOL_BRAWL_CHAMPION_TIER_RANK"}
    }

