def esports_lol_team_standings(shortName, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validation ----
    allowed = {
        "lck", "lpl", "lec", "lcs", "ljl", "vcs", "cblol", "lcl", "lla", "tcl",
        "pcs", "lco", "lta south", "lta north", "lcp", "first stand", "fst",
        "al", "msi", "worlds"
    }
    if shortName is None or not isinstance(shortName, str) or not shortName.strip():
        return _err("VALIDATION_ERROR", "shortName is required and must be a non-empty string.")
    if shortName not in allowed:
        return _err("VALIDATION_ERROR", "shortName must be one of the supported league keys.", allowed=list(sorted(allowed)))

    # ---- Auth / quota ----
    # Ambient auth: search for any quota configuration that can serve reads; if none exist, allow.
    # If a quotas collection exists, enforce it; otherwise proceed without quota enforcement.
    endpoint = "esports-lol-team-standings"
    cred_id = None

    quotas = _load("quotas.json")
    request_logs = _load("request_logs.json")

    def _coerce_int(x, default=None):
        try:
            if x is None:
                return default
            if isinstance(x, bool):
                return default
            return int(x)
        except Exception:
            return default

    def _recent_count(logs, since_ts):
        # logs are expected to have "timestamp" ISO8601
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts >= since_ts:
                cnt += 1
        return cnt

    quota_row = None
    if isinstance(quotas, list) and quotas:
        # prefer a row that applies to this endpoint or globally
        for q in quotas:
            if not isinstance(q, dict):
                continue
            if q.get("service") not in (None, "OP.GG", "OPGG", "opgg", "OP_GG"):
                # allow unknown/None as global
                pass
            ep = q.get("endpoint")
            if ep is None or ep == endpoint:
                quota_row = q
                break

        if quota_row:
            daily_limit = _coerce_int(quota_row.get("daily_limit"))
            window_seconds = _coerce_int(quota_row.get("rate_limit_window_seconds"))
            window_limit = _coerce_int(quota_row.get("rate_limit_max_requests"))
            # Keying: by credential/workspace if present, else global
            scope_key = str(quota_row.get("scope_key") or "global")
            # daily
            if daily_limit is not None:
                day_prefix = now[:10]  # YYYY-MM-DD
                used_today = 0
                for r in request_logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    if str(r.get("scope_key") or "global") != scope_key:
                        continue
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.startswith(day_prefix):
                        used_today += 1
                if used_today >= daily_limit:
                    # log refusal
                    request_logs.append({
                        "id": f"req_{len(request_logs)+1}",
                        "timestamp": now,
                        "endpoint": endpoint,
                        "scope_key": scope_key,
                        "credential_id": cred_id,
                        "status": "QUOTA_EXCEEDED",
                        "latency_ms": int((time.time() - start) * 1000),
                        "params": {"shortName": shortName},
                    })
                    _save("request_logs.json", request_logs)
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

            # rate window
            if window_seconds is not None and window_limit is not None and window_seconds > 0 and window_limit >= 0:
                since = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)).replace(microsecond=0).isoformat() + "Z"
                used = 0
                for r in request_logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    if str(r.get("scope_key") or "global") != scope_key:
                        continue
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts >= since:
                        used += 1
                if used >= window_limit:
                    request_logs.append({
                        "id": f"req_{len(request_logs)+1}",
                        "timestamp": now,
                        "endpoint": endpoint,
                        "scope_key": scope_key,
                        "credential_id": cred_id,
                        "status": "RATE_LIMIT",
                        "latency_ms": int((time.time() - start) * 1000),
                        "params": {"shortName": shortName},
                    })
                    _save("request_logs.json", request_logs)
                    return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=window_seconds)

    # ---- Data lookup: latest active standings snapshot ----
    snapshots = _load("meta_snapshots.json")

    def _dims_match(row):
        return (
            isinstance(row, dict)
            and row.get("game") == "ESPORTS_LOL"
            and row.get("snapshot_type") == "ESPORTS_LOL_TEAM_STANDINGS"
            and row.get("esports_league_short_name") == shortName
        )

    candidates_active = [r for r in snapshots if _dims_match(r) and r.get("status") == "active" and r.get("effective_to") in (None, "")]
    # Choose the most recent effective_from among active currents
    chosen = None
    def _key_eff(r):
        ef = r.get("effective_from")
        return ef if isinstance(ef, str) else ""
    if candidates_active:
        chosen = sorted(candidates_active, key=_key_eff, reverse=True)[0]
    else:
        # Per tool contract: NOT_FOUND when we have no standings snapshot for that league.
        # (No fallback described for esports standings tool.)
        # Log request then return.
        request_logs = _load("request_logs.json")
        request_logs.append({
            "id": f"req_{len(request_logs)+1}",
            "timestamp": now,
            "endpoint": endpoint,
            "scope_key": "global",
            "credential_id": cred_id,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - start) * 1000),
            "params": {"shortName": shortName},
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "No standings snapshot found for the requested league.", shortName=shortName)

    # ---- Log request ----
    request_logs = _load("request_logs.json")
    request_logs.append({
        "id": f"req_{len(request_logs)+1}",
        "timestamp": now,
        "endpoint": endpoint,
        "scope_key": "global",
        "credential_id": cred_id,
        "status": "OK",
        "latency_ms": int((time.time() - start) * 1000),
        "params": {"shortName": shortName},
        "snapshot_id": chosen.get("id"),
    })
    _save("request_logs.json", request_logs)

    return {
        "league": shortName,
        "snapshot": {
            "id": chosen.get("id"),
            "effective_from": chosen.get("effective_from"),
            "source_patch": chosen.get("source_patch"),
            "updated_at": chosen.get("updated_at"),
            "status": chosen.get("status"),
        },
        "data": chosen.get("payload"),
    }

