                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts >= since:
                        used += 1
                if used >= window_limit:
                    request_logs.append({
                        "id": f"req_{len(request_logs)+1}",
                        "timestamp": now,
                        "endpoint": endpoint,
                        "scope_key": scope_key,
                        "credential_id": cred_id,
                        "status": "RATE_LIMIT",
                        "latency_ms": int((time.time() - start) * 1000),
                        "params": {"region": region, "lang": lang},
                    })
                    _save("request_logs.json", request_logs)
                    return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=window_seconds)

    # ---- Snapshot selection rules ----
    snapshots = _load("meta_snapshots.json")
    snapshot_type = "TFT_META_TREND_DECK_LIST"

    def _dims_match(row):
        return (
            isinstance(row, dict)
            and row.get("game") == "TFT"
            and row.get("snapshot_type") == snapshot_type
            and row.get("region") == region
            and row.get("lang") == lang
        )

    # Prefer current active (effective_to is null)
    active = [r for r in snapshots if _dims_match(r) and r.get("status") == "active" and r.get("effective_to") in (None, "")]
    chosen = None

    def _eff_from_key(r):
        ef = r.get("effective_from")
        return ef if isinstance(ef, str) else ""

    if active:
        chosen = sorted(active, key=_eff_from_key, reverse=True)[0]
    else:
        # Fallback to most recent superseded within staleness window (business rule).
        # If no explicit window stored, default to 14 days.
        staleness_days = 14
        if isinstance(quotas, list):
            # allow a config row to override staleness for meta fallbacks
            for q in quotas:
                if isinstance(q, dict) and q.get("endpoint") == "meta_fallback":
                    d = _coerce_int(q.get("staleness_days"))
                    if d is not None and d > 0:
                        staleness_days = d
                    break

        cutoff_dt = datetime.datetime.utcnow() - datetime.timedelta(days=staleness_days)
        cutoff = cutoff_dt.replace(microsecond=0).isoformat() + "Z"

        superseded = [r for r in snapshots if _dims_match(r) and r.get("status") == "superseded"]
        # choose the most recent effective_from where effective_to is >= cutoff OR updated_at >= cutoff
        eligible = []
        for r in superseded:
            et = r.get("effective_to")
            ua = r.get("updated_at")
            if isinstance(et, str) and et >= cutoff:
                eligible.append(r)
            elif isinstance(ua, str) and ua >= cutoff:
                eligible.append(r)
        if eligible:
            chosen = sorted(eligible, key=_eff_from_key, reverse=True)[0]

    if not chosen:
        request_logs = _load("request_logs.json")
        request_logs.append({
            "id": f"req_{len(request_logs)+1}",
            "timestamp": now,
            "endpoint": endpoint,
            "scope_key": "global",
            "credential_id": cred_id,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - start) * 1000),
            "params": {"region": region, "lang": lang},
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "No TFT meta trend deck snapshot exists for the requested region/lang.", region=region, lang=lang)

    # ---- Log request ----
    request_logs = _load("request_logs.json")
    request_logs.append({
        "id": f"req_{len(request_logs)+1}",
        "timestamp": now,
        "endpoint": endpoint,
        "scope_key": "global",
        "credential_id": cred_id,
        "status": "OK",
        "latency_ms": int((time.time() - start) * 1000),
        "params": {"region": region, "lang": lang},
        "snapshot_id": chosen.get("id"),
    })
    _save("request_logs.json", request_logs)

    return {
        "region": region,
        "lang": lang,
        "snapshot": {
            "id": chosen.get("id"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "source_patch": chosen.get("source_patch"),
            "updated_at": chosen.get("updated_at"),
            "status": chosen.get("status"),
        },
        "data": chosen.get("payload"),
    }

