    allowed_langs = {
        "en_US", "ko_KR", "ja_JP", "zh_CN", "zh_TW", "fr_FR", "de_DE", "es_ES",
        "it_IT", "pl_PL", "pt_BR", "ru_RU", "tr_TR", "vi_VN"
    }
    if language is not None:
        if not isinstance(language, str):
            return _err("VALIDATION_ERROR", "language must be a string")
        if language not in allowed_langs:
            return _err("VALIDATION_ERROR", "Unsupported language", allowed=sorted(allowed_langs))

    # service default language when omitted
    lang = language if language is not None else "en_US"

    # --- rate limit / quota + request logging ---
    # Store is not defined in schema; implement observable dynamics with a local request log file.
    # Quota policy (offline approximation): 600 requests/hour per tool across datastore.
    log_file = "request_logs.json"
    logs = _load(log_file)

    # purge old logs for window computations (keep 7 days for audit)
    try:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=7)
        cutoff_iso = cutoff.replace(microsecond=0).isoformat() + "Z"
        logs = [r for r in logs if isinstance(r, dict) and r.get("ts", "9999") >= cutoff_iso]
    except Exception:
        # if logs contain unexpected shapes, keep them; do not fail the call
        pass

    window_start = (datetime.datetime.utcnow() - datetime.timedelta(hours=1)).replace(microsecond=0).isoformat() + "Z"
    recent = [r for r in logs if isinstance(r, dict) and r.get("endpoint") == "tft-meta-item-combinations" and r.get("ts", "") >= window_start]
    if len(recent) >= 600:
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "ts": _now,
            "endpoint": "tft-meta-item-combinations",
            "status": "RATE_LIMIT",
            "latency_ms": int((time.time() - _t0) * 1000),
            "details": {"lang": lang}
        })
        _save(log_file, logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # --- lookup latest active meta snapshot ---
    snapshots = _load("meta_snapshots.json")

    def _dim_match(row):
        if not isinstance(row, dict):
            return False
        if row.get("game") != "TFT":
            return False
        if row.get("snapshot_type") != "TFT_META_ITEM_COMBINATIONS":
            return False
        # Dimensions: language only (region/game_mode/position/etc. null)
        return row.get("lang") == lang

    active = [r for r in snapshots if _dim_match(r) and r.get("status") == "active" and r.get("effective_to") is None]
    chosen = None
    if active:
        # Choose the one with the latest effective_from (should be at most 1 by constraint)
        def _eff(r):
            return r.get("effective_from") or ""
        chosen = sorted(active, key=_eff, reverse=True)[0]
    else:
        # fallback: most recent superseded within allowed staleness window (7 days)
        stale_window = datetime.timedelta(days=7)
        now_dt = datetime.datetime.utcnow()
        superseded = [r for r in snapshots if _dim_match(r) and r.get("status") == "superseded"]
        def _parse_iso(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        cand = []
        for r in superseded:
            et = _parse_iso(r.get("effective_to")) or _parse_iso(r.get("updated_at"))
            if et is None:
                continue
            if now_dt - et <= stale_window:
                cand.append(r)
        if cand:
            chosen = sorted(cand, key=lambda r: (r.get("effective_from") or "", r.get("updated_at") or ""), reverse=True)[0]

    if not chosen:
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "ts": _now,
            "endpoint": "tft-meta-item-combinations",
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - _t0) * 1000),
            "details": {"lang": lang}
        })
