    payload = chosen.get("payload")
    if payload is None:
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "ts": _now,
            "endpoint": "tft-meta-item-combinations",
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - _t0) * 1000),
            "details": {"lang": lang, "snapshot_id": chosen.get("id")}
        })
        _save(log_file, logs)
        return _err("NOT_FOUND", "Snapshot payload missing", snapshot_id=chosen.get("id"))

    # success log
    logs.append({
        "id": "req_" + uuid.uuid4().hex,
        "ts": _now,
        "endpoint": "tft-meta-item-combinations",
        "status": "OK",
        "latency_ms": int((time.time() - _t0) * 1000),
        "details": {"lang": lang, "snapshot_id": chosen.get("id")}
    })
    _save(log_file, logs)

    return {
        "data": payload,
        "meta": {
            "game": "TFT",
            "snapshot_type": "TFT_META_ITEM_COMBINATIONS",
            "lang": lang,
            "snapshot_id": chosen.get("id"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "snapshot_status": chosen.get("status")
        }
    }

