        "TFT_Item_RecurveBow","TFT_Item_BrambleVest","TFT_Item_GiantsBelt","TFT_Item_ThiefsGloves",
        "TFT5_Item_SpearOfShojinRadiant","TFT_Item_NightHarvester","TFT_Item_RapidFireCannon",
        "TFT_Item_Artifact_TalismanOfAscension","TFT5_Item_LeviathanRadiant","TFT14_MordekaiserCyberneticItem_Radiant",
        "TFT5_Item_TrapClawRadiant","TFT_Item_Artifact_LichBane"
    }
    if itemId not in allowed:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "itemId is not in the supported itemId set", itemId=itemId)

    # Must correspond to an active game_catalog row
    catalog = _load("game_catalog.json")
    if not isinstance(catalog, list):
        catalog = []
    ok_item = False
    for r in catalog:
        if r.get("game") == "TFT" and r.get("entity_type") == "TFT_ITEM" and r.get("external_key") == itemId and r.get("status") == "active":
            ok_item = True
            break
    if not ok_item:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "ItemId does not correspond to an active TFT item in catalog", itemId=itemId)

    # Find latest snapshot: snapshot_type=TFT_RECOMMEND_CHAMPION_FOR_ITEM, game=TFT, tft_item_external_key=itemId
    snapshots = _load("meta_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []

    def _dims_match(s):
        if s.get("game") != "TFT":
            return False
        if s.get("snapshot_type") != "TFT_RECOMMEND_CHAMPION_FOR_ITEM":
            return False
        if s.get("tft_item_external_key") != itemId:
            return False
        # Dimensions for this snapshot type: only item key required; others should be null/any.
        return True

    def _parse_dt(x):
        if not isinstance(x, str):
            return None
        try:
            return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
        except Exception:
            return None

    active = []
    superseded = []
    for s in snapshots:
        if not _dims_match(s):
            continue
        st = s.get("status")
        if st == "active" and s.get("effective_to") in (None, ""):
            active.append(s)
        elif st == "superseded":
            superseded.append(s)

    chosen = None
    if active:
        # pick most recent effective_from
        active.sort(key=lambda x: (_parse_dt(x.get("effective_from")) or datetime.datetime.min), reverse=True)
        chosen = active[0]
    else:
        # fallback: most recent superseded within staleness window (30 days)
        superseded.sort(key=lambda x: (_parse_dt(x.get("effective_from")) or datetime.datetime.min), reverse=True)
        if superseded:
            latest = superseded[0]
            ef = _parse_dt(latest.get("effective_from")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - ef <= datetime.timedelta(days=30):
                chosen = latest

    if not chosen:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No recommendation snapshot available for this itemId", itemId=itemId)

    payload = chosen.get("payload")
    if not isinstance(payload, dict):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Snapshot payload missing or invalid", snapshot_id=chosen.get("id"))

    # Interpret payload: expected to include recommended champions list
    recs = None
    for key in ("recommendations", "champions", "data", "items"):
        if key in payload:
            recs = payload.get(key)
            break

    # If payload is already the list, accept it
    if recs is None and isinstance(payload, list):
        recs = payload

    # If payload has a specific item key mapping
    if isinstance(recs, dict) and itemId in recs:
        recs = recs.get(itemId)

    if not isinstance(recs, list) or len(recs) == 0:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No recommendation data for itemId in the current snapshot", itemId=itemId, snapshot_id=chosen.get("id"))

    # Validate champions in recs correspond to active TFT champions where possible
    champ_keys = set()
    for r in catalog:
        if r.get("game") == "TFT" and r.get("entity_type") == "TFT_CHAMPION" and r.get("status") == "active" and isinstance(r.get("external_key"), str):
            champ_keys.add(r["external_key"])

    filtered = []
    for entry in recs:
        if isinstance(entry, dict):
            ck = entry.get("championId") or entry.get("champion_external_key") or entry.get("tft_champion_external_key") or entry.get("external_key")
            if isinstance(ck, str) and ck in champ_keys:
                filtered.append(entry)
            else:
                # keep entries even if unknown, but mark; do not fabricate
                filtered.append(entry)
        else:
            filtered.append(entry)

    _log("ok")
    return {
        "itemId": itemId,
        "snapshot": {
            "id": chosen.get("id"),
            "status": chosen.get("status"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "source_patch": chosen.get("source_patch")
        },
        "recommendations": filtered
    }

def tft_play_style_comment(region, puuid, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    request_log_file = "request_logs.json"
    quota_file = "usage_quotas.json"
    endpoint = "tft-play-style-comment"
    status_code = "ok"
    credential_used = None

    def _log_and_return(payload):
        nonlocal status_code
        latency_ms = int((time.time() - start) * 1000)
        logs = _load(request_log_file)
        if isinstance(logs, list):
            logs.append(
                {
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": endpoint,
                    "credential_id": credential_used,
                    "status": status_code,
                    "latency_ms": latency_ms,
                    "timestamp": now,
                }
            )
            _save(request_log_file, logs)
        return payload

    def _enforce_rate_limit():
        quotas = _load(quota_file)
        if not isinstance(quotas, list):
            return None
        policies = [q for q in quotas if isinstance(q, dict) and q.get("enabled", True)]
        endpoint_policies = [q for q in policies if q.get("endpoint") in (None, "", endpoint)]
        if not endpoint_policies:
            return None
        def lim(q):
            try:
                return int(q.get("limit", 0))
            except Exception:
                return 0
        policy = sorted(endpoint_policies, key=lim)[0]
        window_s = policy.get("window_seconds")
        limit = policy.get("limit")
        if not isinstance(window_s, int) or window_s <= 0 or not isinstance(limit, int) or limit < 0:
            return None

        logs = _load(request_log_file)
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                tsv = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if tsv >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", endpoint=endpoint, limit=limit, window_seconds=window_s)
        return None

    rl = _enforce_rate_limit()
    if rl is not None:
        status_code = "rate_limited"
        return _log_and_return(rl)

    # --- Validation ---
    allowed_regions = {"KR", "BR", "EUNE", "EUW", "LAN", "LAS", "NA", "OCE", "RU", "TR", "JP", "PH", "SG", "TH", "TW", "VN", "ME"}
    if not isinstance(region, str) or region.strip() == "":
        status_code = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "region is required"))
    region = region.strip()
    if region not in allowed_regions:
        status_code = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "Unsupported region", region=region))

    if not isinstance(puuid, str) or puuid.strip() == "":
        status_code = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "puuid is required"))
    puuid = puuid.strip()
    # PUUIDs are typically 70+ chars, url-safe; enforce a conservative pattern/length.
    if len(puuid) < 10 or len(puuid) > 128 or not re.match(r"^[A-Za-z0-9\-_]+$", puuid):
        status_code = "validation_error"
        return _log_and_return(_err("VALIDATION_ERROR", "puuid is malformed", puuid=puuid))

    players = _load("players.json")
    if not isinstance(players, list):
        status_code = "unauthorized"
        return _log_and_return(_err("UNAUTHORIZED", "Datastore unavailable"))

    player = None
    for p in players:
        if not isinstance(p, dict):
            continue
        if p.get("product") != "TFT":
            continue
        if p.get("region") != region:
            continue
        if p.get("puuid") != puuid:
            continue
        player = p
        break

    if player is None:
        status_code = "not_found"
        return _log_and_return(_err("NOT_FOUND", "Player not present in cache for region/puuid", region=region, puuid=puuid))

    if player.get("status") in ("disabled", "not_found"):
        status_code = "not_found"
        return _log_and_return(_err("NOT_FOUND", "Player cache entry is not active", player_id=player.get("id"), status=player.get("status")))

    matches = _load("player_matches.json")
    if not isinstance(matches, list):
        status_code = "unauthorized"
        return _log_and_return(_err("UNAUTHORIZED", "Datastore unavailable"))

    pid = player.get("id")
    if not isinstance(pid, str) or not pid:
        status_code = "not_found"
        return _log_and_return(_err("NOT_FOUND", "Player cache entry is invalid", puuid=puuid, region=region))

    tft_matches = []
    for m in matches:
        if not isinstance(m, dict):
            continue
        if m.get("player_id") != pid:
            continue
        if m.get("product") != "TFT":
            continue
        if m.get("status") != "active":
            continue
        # Region may be null in matches, but if present, must match requested region
        if m.get("region") not in (None, "", region):
            continue
        tft_matches.append(m)

    # If no analyzable matches, NOT_FOUND (per tool description)
    if not tft_matches:
        status_code = "not_found"
        return _log_and_return(
            _err(
                "NOT_FOUND",
                "No analyzable match data for this player",
                player_id=pid,
                region=region,
                puuid=puuid,
            )
        )

    def _parse_dt(v):
        if not isinstance(v, str):
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    tft_matches.sort(key=lambda m: (_parse_dt(m.get("played_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
    recent = tft_matches[:50]

    # Summarize champion/units tendencies from summary_payload if available
    champ_counts = {}
    placements = []
    modes = {}
    for m in recent:
        sp = m.get("summary_payload")
        if not isinstance(sp, dict):
            continue
        # Attempt to extract "carry" / "champion" fields with common names
        champ = sp.get("carry") or sp.get("carryChampion") or sp.get("unit") or sp.get("champion") or sp.get("primary_unit")
        if isinstance(champ, str) and champ.strip():
            champ_counts[champ.strip()] = champ_counts.get(champ.strip(), 0) + 1
        placement = sp.get("placement") or sp.get("rank") or sp.get("finalPlacement")
        if isinstance(placement, int):
            placements.append(placement)
        elif isinstance(placement, str) and placement.isdigit():
            placements.append(int(placement))
        mode = m.get("queue_or_mode") or sp.get("queue") or sp.get("mode")
        if isinstance(mode, str) and mode.strip():
            modes[mode.strip()] = modes.get(mode.strip(), 0) + 1

    if not champ_counts and not placements and not modes:
        status_code = "not_found"
        return _log_and_return(
            _err(
                "NOT_FOUND",
                "Player has matches but no analyzable fields in cached summaries",
                player_id=pid,
            )
        )

    top_champs = sorted(champ_counts.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
    avg_place = (sum(placements) / len(placements)) if placements else None
    common_mode = sorted(modes.items(), key=lambda kv: (-kv[1], kv[0]))[0][0] if modes else None

    # Provide a concise, derived commentary
    parts = []
    if top_champs:
        parts.append("Most played carries/units recently: " + ", ".join([f"{c} ({n})" for c, n in top_champs]) + ".")
    if avg_place is not None:
        parts.append(f"Average placement over last {len(placements)} games: {avg_place:.2f}.")
    if common_mode:
        parts.append(f"Most common queue/mode: {common_mode}.")

    comment = " ".join(parts).strip()

    status_code = "ok"
    return _log_and_return(
        {
            "region": region,
            "puuid": puuid,
            "player": {
                "id": player.get("id"),
                "game_name": player.get("game_name"),
                "tag_line": player.get("tag_line"),
                "last_renewed_at": player.get("last_renewed_at"),
                "status": player.get("status"),
            },
            "sample_size": len(recent),
            "commentary": comment,
            "signals": {
                "top_units": [{"unit": c, "games": n} for c, n in top_champs],
                "average_placement": avg_place,
                "common_mode": common_mode,
            },
        }
    )

def valorant_meta_maps(region, lang, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    request_logs_file = "request_logs.json"
    usage_file = "usage_counters.json"
    endpoint = "valorant-meta-maps"

    def _log(status, credential_id=None, error_code=None):
        logs = _load(request_logs_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - _t0) * 1000)
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "ts": now
        })
        _save(request_logs_file, logs)

        counters = _load(usage_file)
        if not isinstance(counters, dict):
            counters = {}
        day = now[:10]
        counters.setdefault("by_day", {})
        counters["by_day"].setdefault(day, {})
        counters["by_day"][day].setdefault(endpoint, 0)
        counters["by_day"][day][endpoint] += 1
        _save(usage_file, counters)

    def _rate_limited():
        logs = _load(request_logs_file)
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-2000:]):
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str) or len(ts) < 20:
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if t < cutoff:
                continue
            c += 1
            if c >= 120:
                return True
        return False

    # additionalProperties=false
    if _extra:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported parameters provided", unsupported=list(_extra.keys()))

    if _rate_limited():
        _log("error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Validate required params
    if not isinstance(region, str) or not region:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "region is required and must be a non-empty string")
    if not isinstance(lang, str) or not lang:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "lang is required and must be a non-empty string")

    # Tool param enum is broad, but business rule restricts Valorant leaderboard regions; for maps meta, enforce same Valorant region set.
    allowed_valorant_regions = {"AP", "BR", "EU", "KR", "LATAM", "NA"}
    if region not in allowed_valorant_regions:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported Valorant region for this endpoint", region=region, allowed=sorted(allowed_valorant_regions))

    allowed_langs = {
        "ar_AE","cs_CZ","de_DE","el_GR","en_US","en_AU","en_GB","en_PH","en_SG","es_AR","es_ES","es_MX","fr_FR",
        "hu_HU","it_IT","ja_JP","ko_KR","pl_PL","pt_BR","ro_RO","ru_RU","th_TH","tr_TR","vi_VN","zh_CN","zh_MY","zh_TW"
    }
    if lang not in allowed_langs:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported lang", lang=lang)

    snapshots = _load("meta_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []

    def _parse_dt(x):
        if not isinstance(x, str):
            return None
        try:
            return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
        except Exception:
            return None

    # Lookup: snapshot_type=VALORANT_META_MAPS, game=VALORANT, region+lang match; latest active, else superseded within 30 days
    matches = []
    for s in snapshots:
        if s.get("game") != "VALORANT":
            continue
        if s.get("snapshot_type") != "VALORANT_META_MAPS":
            continue
        if s.get("region") != region:
            continue
        if s.get("lang") != lang:
            continue
        matches.append(s)

    active = [s for s in matches if s.get("status") == "active" and s.get("effective_to") in (None, "")]
    chosen = None
    if active:
        active.sort(key=lambda x: (_parse_dt(x.get("effective_from")) or datetime.datetime.min), reverse=True)
        chosen = active[0]
    else:
        superseded = [s for s in matches if s.get("status") == "superseded"]
        superseded.sort(key=lambda x: (_parse_dt(x.get("effective_from")) or datetime.datetime.min), reverse=True)
        if superseded:
            latest = superseded[0]
            ef = _parse_dt(latest.get("effective_from")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - ef <= datetime.timedelta(days=30):
                chosen = latest

    if not chosen:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No Valorant maps meta snapshot available for the requested region/lang", region=region, lang=lang)

    payload = chosen.get("payload")
    if not isinstance(payload, (dict, list)):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Snapshot payload missing or invalid", snapshot_id=chosen.get("id"))

    _log("ok")
    return {
        "region": region,
        "lang": lang,
        "snapshot": {
            "id": chosen.get("id"),
            "status": chosen.get("status"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "source_patch": chosen.get("source_patch")
        },
        "data": payload
    }

def valorant_meta_characters(region, lang, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- validation ----
    allowed_region = {"KR", "BR", "EUNE", "EUW", "LAN", "LAS", "NA", "OCE", "RU", "TR", "JP", "PH", "SG", "TH", "TW", "VN", "ME", "SEA", "AP", "EU", "LATAM"}
    allowed_lang = {"ar_AE", "cs_CZ", "de_DE", "el_GR", "en_US", "en_AU", "en_GB", "en_PH", "en_SG", "es_AR", "es_ES", "es_MX", "fr_FR", "hu_HU", "it_IT", "ja_JP", "ko_KR", "pl_PL", "pt_BR", "ro_RO", "ru_RU", "th_TH", "tr_TR", "vi_VN", "zh_CN", "zh_MY", "zh_TW"}

    if not isinstance(region, str) or region not in allowed_region:
        return _err("VALIDATION_ERROR", "Invalid region.", allowed=sorted(list(allowed_region)))
    if not isinstance(lang, str) or lang not in allowed_lang:
        return _err("VALIDATION_ERROR", "Invalid lang.", allowed=sorted(list(allowed_lang)))

    meta = _load("meta_snapshots.json")

    # Allowed staleness window for fallback to superseded snapshot
    staleness_days = 14
    now = datetime.datetime.utcnow()
    cutoff = now - datetime.timedelta(days=staleness_days)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v[:-1] if v.endswith("Z") else v
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _dims_match(r):
        return (
            r.get("snapshot_type") == "VALORANT_META_CHARACTERS"
            and r.get("game") == "VALORANT"
            and r.get("region") == region
            and r.get("lang") == lang
        )

    candidates_active = [r for r in meta if _dims_match(r) and r.get("status") == "active" and r.get("effective_to") in (None, "")]
    chosen = None

    if candidates_active:
        # pick latest effective_from (then updated_at)
        def _key(r):
            ef = _parse_dt(r.get("effective_from")) or datetime.datetime.min
            ua = _parse_dt(r.get("updated_at")) or datetime.datetime.min
            return (ef, ua)

        chosen = sorted(candidates_active, key=_key, reverse=True)[0]
    else:
        # fallback to most recent superseded within staleness window
        candidates_sup = [r for r in meta if _dims_match(r) and r.get("status") == "superseded"]
        if candidates_sup:
            def _key2(r):
                # prefer newest effective_to, else effective_from
                et = _parse_dt(r.get("effective_to")) or datetime.datetime.min
                ef = _parse_dt(r.get("effective_from")) or datetime.datetime.min
                ua = _parse_dt(r.get("updated_at")) or datetime.datetime.min
                return (et, ef, ua)

            best = sorted(candidates_sup, key=_key2, reverse=True)[0]
            # consider stale if its end or start time is too old
            age_ref = _parse_dt(best.get("effective_to")) or _parse_dt(best.get("effective_from")) or datetime.datetime.min
            if age_ref >= cutoff:
                chosen = best

    # ---- request logging (best-effort; do not fail call if log can't be persisted) ----
    # Service schema did not define a request-log collection; keep no-op dynamics.
    # (If a vendor log file is present in store, write into it.)
    for log_name in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
        p = os.path.join(_DB, log_name)
        if os.path.exists(p):
            logs = _load(log_name)
            status = "ok" if chosen is not None else "ok_empty"
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "valorant-meta-characters",
                "timestamp": ts,
                "region": region,
                "lang": lang,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(log_name, logs)
            break

    if chosen is None:
        return {
            "snapshot": None,
            "data": None,
            "meta": {
                "snapshot_type": "VALORANT_META_CHARACTERS",
                "region": region,
                "lang": lang,
                "found": False,
            },
        }

    return {
        "snapshot": {
            "id": chosen.get("id"),
            "game": chosen.get("game"),
            "snapshot_type": chosen.get("snapshot_type"),
            "region": chosen.get("region"),
            "lang": chosen.get("lang"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "status": chosen.get("status"),
            "source_patch": chosen.get("source_patch"),
            "updated_at": chosen.get("updated_at"),
        },
        "data": chosen.get("payload"),
        "meta": {
            "found": True,
            "fallback_used": chosen.get("status") != "active",
        },
    }

