def valorant_agents_composition_with_map(mapId, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / quota-ratelimit (best-effort if no collection exists) ----
    def _log(status, credential_used=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "valorant-agents-composition-with-map",
                    "params": {"mapId": mapId},
                    "credential_used": credential_used,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": latency_ms,
                    "created_at": now
                })
                _save(fname, logs)
                break

    # ---- validate ----
    if not isinstance(mapId, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mapId must be a string.")
    mapId = mapId.strip()
    if mapId == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mapId must be non-empty.")

    catalog = _load("game_catalog.json")
    map_row = None
    for r in catalog:
        if r.get("game") == "VALORANT" and r.get("entity_type") == "VALORANT_MAP" and r.get("external_key") == mapId:
            map_row = r
            break
    if not map_row:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mapId is not a valid Valorant map identifier.", mapId=mapId)
    if map_row.get("status") != "active":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mapId refers to a deprecated Valorant map.", mapId=mapId)

    # ---- find latest active snapshot (fallback to superseded within staleness) ----
    snapshots = _load("meta_snapshots.json")
    snapshot_type = "VALORANT_AGENTS_COMPOSITION_WITH_MAP"

    def _dim_match(s):
        return (
            s.get("snapshot_type") == snapshot_type and
            s.get("game") == "VALORANT" and
            (s.get("valorant_map_external_key") == mapId)
        )

    candidates = [s for s in snapshots if _dim_match(s)]
    active = [s for s in candidates if s.get("status") == "active" and s.get("effective_to") in (None, "")]
    chosen = None
    if active:
        # If multiple (shouldn't), pick max effective_from then updated_at.
        def _key(s):
            return (s.get("effective_from") or "", s.get("updated_at") or "", s.get("created_at") or "")
        chosen = sorted(active, key=_key, reverse=True)[0]
    else:
        # fallback: most recent superseded within staleness window
        superseded = [s for s in candidates if s.get("status") == "superseded"]
        if superseded:
            superseded_sorted = sorted(
                superseded,
                key=lambda s: (s.get("effective_from") or "", s.get("updated_at") or "", s.get("created_at") or ""),
                reverse=True
            )
            best = superseded_sorted[0]
            # allowed staleness: 30 days
            staleness_days = 30
            ef = best.get("effective_from")
            ok = False
            if isinstance(ef, str) and ef:
                try:
                    # parse ISO; accept trailing Z
                    ef_s = ef[:-1] if ef.endswith("Z") else ef
                    dt = datetime.datetime.fromisoformat(ef_s)
                    age = datetime.datetime.utcnow() - dt
                    ok = age <= datetime.timedelta(days=staleness_days)
                except Exception:
                    ok = False
            if ok:
                chosen = best

    if not chosen:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No agent composition snapshot exists for the requested map.", mapId=mapId)

    _log("ok")
    # Return envelope with snapshot metadata + payload
    return {
        "mapId": mapId,
        "snapshot": {
            "id": chosen.get("id"),
            "snapshot_type": chosen.get("snapshot_type"),
            "game": chosen.get("game"),
            "status": chosen.get("status"),
            "effective_from": chosen.get("effective_from"),
            "effective_to": chosen.get("effective_to"),
            "source_patch": chosen.get("source_patch"),
            "updated_at": chosen.get("updated_at"),
        },
        "data": chosen.get("payload")
    }

