def valorant_player_match_history(gameName, tagLine, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request log (best-effort if collection exists)
    def _log(status_code, credential_used=None, error_code=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": "valorant-player-match-history",
                "credential_used": credential_used,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": now
            })
            _save("request_logs.json", logs)

    # Validation
    if not isinstance(gameName, str) or not gameName.strip():
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "gameName is required and must be a non-empty string.", field="gameName")
    if not isinstance(tagLine, str) or not tagLine.strip():
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tagLine is required and must be a non-empty string.", field="tagLine")

    # Normalize riot id similarly to schema's intent
    gn = gameName.strip()
    tl = tagLine.strip()
    normalized = (gn.lower().strip() + "#" + tl.lower().strip()).replace(" ", "")

    players = _load("players.json")
    if not isinstance(players, list):
        _log(500, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Players cache unavailable.")

    # Valorant match history tool does not specify region; resolve any VALORANT profile matching normalized id.
    candidates = [p for p in players
                  if isinstance(p, dict)
                  and p.get("product") == "VALORANT"
                  and p.get("normalized_riot_id") == normalized]

    if not candidates:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Player not found in cache. Run profile ingestion/renewal first.", normalized_riot_id=normalized)

    # Prefer active players; if none active, still allow if present (but NOT_FOUND if disabled?)
    active = [p for p in candidates if p.get("status") == "active"]
    player = active[0] if active else candidates[0]

    if player.get("status") == "disabled":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Player is disabled in cache.", player_id=player.get("id"))

    matches = _load("player_matches.json")
    if not isinstance(matches, list):
        _log(500, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Match cache unavailable.")

    pm = [m for m in matches
          if isinstance(m, dict)
          and m.get("player_id") == player.get("id")
          and m.get("product") == "VALORANT"
          and m.get("status") == "active"]

    if not pm:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No cached match history for this player.", player_id=player.get("id"))

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            # Accept Z or offset-less ISO; normalize
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    pm.sort(key=lambda r: (_parse_dt(r.get("played_at")) or datetime.datetime.min), reverse=True)

    # Vendor description mentions pagination/cursor when supported; tool signature has none, so return full list.
    # Envelope provides metadata so caller can implement client-side pagination.
    result = {
        "player": {
            "id": player.get("id"),
            "product": player.get("product"),
            "game_name": player.get("game_name"),
            "tag_line": player.get("tag_line"),
            "normalized_riot_id": player.get("normalized_riot_id"),
            "region": player.get("region"),
            "last_renewed_at": player.get("last_renewed_at"),
            "status": player.get("status")
        },
        "matches": pm,
        "meta": {
            "total": len(pm),
            "ordered_by": "played_at_desc",
            "has_more": False,
            "next_cursor": None
        }
    }

    _log(200)
    return result

def game_catalog_list(game, entity_type, status=None, external_key=None, lang=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None, error_code=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": "game-catalog-list",
                "credential_used": credential_used,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": now
            })
            _save("request_logs.json", logs)

    # Defaults
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50

    # Validation: types
    if not isinstance(game, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "game must be a string.", field="game")
    if not isinstance(entity_type, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "entity_type must be a string.", field="entity_type")
    if status is not None and not isinstance(status, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be a string when provided.", field="status")
    if external_key is not None and not isinstance(external_key, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "external_key must be a string when provided.", field="external_key")
    if lang is not None and not isinstance(lang, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "lang must be a string when provided.", field="lang")
    if not isinstance(page, int) or page < 1:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", field="page_size")

    # Validation: enums from tool
    allowed_game = {"LOL", "TFT", "VALORANT", "ESPORTS"}
    if game not in allowed_game:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid game.", field="game", allowed=sorted(allowed_game))

    allowed_entity = {"CHAMPION", "ITEM", "RUNE", "SPELL", "MAP", "AGENT", "WEAPON", "AUGMENT", "TRAIT", "LEAGUE", "TEAM", "TOURNAMENT"}
    if entity_type not in allowed_entity:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid entity_type.", field="entity_type", allowed=sorted(allowed_entity))

    allowed_status = {"active", "deprecated"}
    if status is not None and status not in allowed_status:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(allowed_status))

    allowed_lang = {"en_US", "ko_KR", "ja_JP", "zh_CN", "zh_TW", "vi_VN", "th_TH", "id_ID", "ms_MY", "pt_BR", "es_ES", "es_MX", "fr_FR", "de_DE", "it_IT", "ru_RU", "tr_TR", "pl_PL"}
    if lang is not None and lang not in allowed_lang:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid lang.", field="lang", allowed=sorted(allowed_lang))

    if external_key is not None and len(external_key.strip()) < 1:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "external_key must be a non-empty string when provided.", field="external_key")

    # Authorization:
    # No explicit credentials exist in this schema, so treat as ambient-auth and allow if the datastore contains
    # at least one row for the requested game namespace; otherwise UNAUTHORIZED.
    catalog = _load("game_catalog.json")
    if not isinstance(catalog, list):
        _log(500, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Catalog datastore unavailable.")

    # Map tool params to schema enums
    game_map = {"LOL": "LOL", "TFT": "TFT", "VALORANT": "VALORANT", "ESPORTS": "ESPORTS_LOL"}
    mapped_game = game_map.get(game)

    entity_map = {
        ("LOL", "CHAMPION"): "LOL_CHAMPION",
        ("LOL", "ITEM"): "TFT_ITEM",  # not actually LoL items in schema; will yield empty
        ("TFT", "CHAMPION"): "TFT_CHAMPION",
        ("TFT", "ITEM"): "TFT_ITEM",
        ("VALORANT", "MAP"): "VALORANT_MAP",
        ("VALORANT", "AGENT"): "VALORANT_AGENT",
        ("ESPORTS_LOL", "LEAGUE"): "ESPORTS_LEAGUE",
        ("ESPORTS_LOL", "TOURNAMENT"): "ESPORTS_LEAGUE",
    }
    mapped_entity = entity_map.get((mapped_game, entity_type))

    # If tool asks for an entity type not supported by schema, return empty set (not an error).
    # But still must pass authorization: ensure game namespace exists at all in catalog.
    any_for_game = any(isinstance(r, dict) and r.get("game") == mapped_game for r in catalog)
    if not any_for_game:
        _log(401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token cannot access the requested game (no accessible catalog namespace).", game=game)

    rows = [r for r in catalog if isinstance(r, dict) and r.get("game") == mapped_game]
    if mapped_entity is not None:
        rows = [r for r in rows if r.get("entity_type") == mapped_entity]
    else:
        rows = []

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if external_key is not None:
        ek = external_key.strip()
        rows = [r for r in rows if r.get("external_key") == ek]

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    rows.sort(key=lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime.min), reverse=True)

    total = len(rows)
    start_i = (page - 1) * page_size
    end_i = start_i + page_size
    page_rows = rows[start_i:end_i]
    has_more = end_i < total

    # Apply localization hint (non-destructive): add a computed display_name if possible
    out_rows = []
    for r in page_rows:
        rr = dict(r)
        if lang is not None and isinstance(rr.get("localized_names"), dict):
            loc = rr["localized_names"].get(lang)
            if isinstance(loc, str) and loc.strip():
                rr["display_name"] = loc
            else:
                rr["display_name"] = rr.get("display_name_default")
        else:
            rr["display_name"] = rr.get("display_name_default")
        out_rows.append(rr)

    resp = {
        "data": out_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_cursor": None,
            "order": "updated_at_desc",
            "mapped": {
                "game": mapped_game,
                "entity_type": mapped_entity
            }
        }
    }

    _log(200)
    return resp

