def game_catalog_update(id, display_name_default=None, localized_names=None, metadata=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "game-catalog-update"
    call_status = "ok"

    req_file = "request_log.json"
    reqs = _load(req_file)

    try:
        # Validate inputs
        if not isinstance(id, str) or not id.strip():
            call_status = "error"
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

        if display_name_default is not None:
            if not isinstance(display_name_default, str) or not display_name_default.strip():
                call_status = "error"
                return _err("VALIDATION_ERROR", "display_name_default must be a non-empty string", field="display_name_default")

        if localized_names is not None:
            if not isinstance(localized_names, dict):
                call_status = "error"
                return _err("VALIDATION_ERROR", "localized_names must be an object/dict", field="localized_names")
            for k, v in localized_names.items():
                if not isinstance(k, str) or not k.strip():
                    call_status = "error"
                    return _err("VALIDATION_ERROR", "localized_names keys must be non-empty strings", field="localized_names")
                if not isinstance(v, str):
                    call_status = "error"
                    return _err("VALIDATION_ERROR", "localized_names values must be strings", field="localized_names", key=k)

        if metadata is not None and not isinstance(metadata, dict):
            call_status = "error"
            return _err("VALIDATION_ERROR", "metadata must be an object/dict", field="metadata")

        if status is not None:
            if not isinstance(status, str):
                call_status = "error"
                return _err("VALIDATION_ERROR", "status must be a string", field="status")
            if status not in ("active", "deprecated"):
                call_status = "error"
                return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "deprecated"])

        rows = _load("game_catalog.json")
        idx = None
        row = None
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == id:
                idx = i
                row = r
                break

        if row is None:
            call_status = "error"
            return _err("NOT_FOUND", "Catalog entry not found", id=id)

        # Ambient auth: no credential param; datastore contains no ACLs; cannot deny by token.
        # Therefore authorized.

        # Enforce constraints that apply on update
        # external_key/display_name_default must remain non-empty
        if display_name_default is None:
            if not isinstance(row.get("display_name_default"), str) or not row.get("display_name_default", "").strip():
                call_status = "error"
                return _err("VALIDATION_ERROR", "display_name_default cannot be empty")
        else:
            if not display_name_default.strip():
                call_status = "error"
                return _err("VALIDATION_ERROR", "display_name_default cannot be empty")

        if not isinstance(row.get("external_key"), str) or not row.get("external_key", "").strip():
            call_status = "error"
            return _err("VALIDATION_ERROR", "external_key cannot be empty", field="external_key")

        # Status transition rules
        lifecycle = {
            "active": ["deprecated"],
            "deprecated": ["active"]
        }
        if status is not None:
            cur = row.get("status")
            if cur not in lifecycle:
                call_status = "error"
                return _err("VALIDATION_ERROR", "Row has invalid current status", current=cur)
            if status != cur and status not in lifecycle.get(cur, []):
                call_status = "error"
                return _err("INVALID_TRANSITION", "Invalid status transition", from_status=cur, to_status=status)

        # uniqueness constraint: unique(game, entity_type, external_key)
        game = row.get("game")
        entity_type = row.get("entity_type")
        ext = row.get("external_key")
        if not isinstance(game, str) or not isinstance(entity_type, str) or not isinstance(ext, str):
            call_status = "error"
            return _err("VALIDATION_ERROR", "Row has invalid key fields for uniqueness check")
        for r in rows:
            if not isinstance(r, dict): 
                continue
            if r.get("id") == id:
                continue
            if r.get("game") == game and r.get("entity_type") == entity_type and r.get("external_key") == ext:
                call_status = "error"
                return _err("CONFLICT", "unique(game, entity_type, external_key) violated", game=game, entity_type=entity_type, external_key=ext)

        # Apply updates (vendor semantics: metadata merged/replaced per semantics; we'll deep-merge dicts shallowly)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        updated = dict(row)

        if display_name_default is not None:
            updated["display_name_default"] = display_name_default

        if localized_names is not None:
            # Replace whole localized_names map (common API semantics)
            updated["localized_names"] = dict(localized_names)

        if metadata is not None:
            # Merge into existing metadata dict; if existing not dict, replace
            cur_meta = updated.get("metadata")
            if isinstance(cur_meta, dict):
                merged = dict(cur_meta)
                merged.update(metadata)
                updated["metadata"] = merged
            else:
                updated["metadata"] = dict(metadata)

        if status is not None:
            updated["status"] = status

        updated["updated_at"] = now
        if "created_at" not in updated or not updated.get("created_at"):
            updated["created_at"] = now

        rows[idx] = updated
        _save("game_catalog.json", rows)

        return {
            "data": updated,
            "meta": {
                "updated": True
            }
        }
    except (TypeError, ValueError) as e:
        call_status = "error"
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))
    except Exception as e:
        call_status = "error"
        return _err("CONFLICT", "Unexpected server condition", detail=str(e))
    finally:
        try:
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            latency_ms = int((time.time() - t0) * 1000)
            reqs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential": None,
                "status": call_status,
                "latency_ms": latency_ms,
                "ts": now
            })
            _save(req_file, reqs)
        except Exception:
            pass

def meta_snapshots_list(game, snapshot_type, status=None, region=None, lang=None, game_mode=None, position=None, champion_external_key=None, tft_champion_external_key=None, tft_item_external_key=None, valorant_map_external_key=None, esports_league_short_name=None, format=None, source_patch=None, effective_from_lte=None, effective_to_gte=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None
    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    # --- audit/rate-limit dynamics (best-effort based on request_logs.json if present) ---
    def _log_call(endpoint, status_code, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_code,
            "timestamp": _iso(_now),
            "latency_ms": latency_ms,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        # Simple global limit: 120 requests/minute across the datastore
        window_s = 60
        limit = 120
        cutoff = _now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            dt = _parse_dt(ts, "timestamp")
            if isinstance(dt, datetime.datetime):
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                if dt >= cutoff:
                    cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit, window_seconds=window_s)
        return None

    rl = _rate_limit_check()
    if rl:
        _log_call("meta-snapshots-list", "RATE_LIMIT")
        return rl

    # --- validate required ---
    allowed_game = {"LOL", "TFT", "VALORANT", "ESPORTS"}
    if not isinstance(game, str) or game not in allowed_game:
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid game", field="game", allowed=sorted(list(allowed_game)))

    allowed_snapshot_type = {
        "LOL_CHAMPION_ANALYSIS",
        "LOL_CHAMPION_POSITIONS",
        "LOL_CHAMPION_LEADERBOARD",
        "TFT_META",
        "TFT_BUILDS",
        "TFT_LEADERBOARD",
        "VALORANT_LEADERBOARD",
        "VALORANT_AGENT_META",
        "ESPORTS_STANDINGS",
        "ESPORTS_SCHEDULE",
    }
    if not isinstance(snapshot_type, str) or snapshot_type not in allowed_snapshot_type:
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid snapshot_type", field="snapshot_type", allowed=sorted(list(allowed_snapshot_type)))

    allowed_status = {"building", "active", "superseded", "failed"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(list(allowed_status)))

    allowed_lang = {"en_US", "ko_KR", "ja_JP", "zh_CN", "zh_TW", "vi_VN", "th_TH", "id_ID", "ms_MY", "pt_BR", "es_ES", "es_MX", "fr_FR", "de_DE", "it_IT", "ru_RU", "tr_TR", "pl_PL"}
    if lang is not None and (not isinstance(lang, str) or lang not in allowed_lang):
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid lang", field="lang", allowed=sorted(list(allowed_lang)))

    allowed_position = {"TOP", "JUNGLE", "MID", "ADC", "SUPPORT"}
    if position is not None and (not isinstance(position, str) or position not in allowed_position):
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid position", field="position", allowed=sorted(list(allowed_position)))

    allowed_format = {"csv", "json", "json_zip"}
    if format is not None and (not isinstance(format, str) or format not in allowed_format):
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid format", field="format", allowed=sorted(list(allowed_format)))

    # page defaults
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid page", field="page", minimum=1)
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid page_size", field="page_size", minimum=1, maximum=200)

    # region validation per product family (tool rule)
    lol_style_regions = {"KR", "BR", "EUNE", "EUW", "LAN", "LAS", "NA", "OCE", "RU", "TR", "JP", "PH", "SG", "TH", "TW", "VN", "ME", "SEA"}
    global_regions = {"AP", "EU", "LATAM"}  # present in schema; kept for non-valorant leaderboard snapshots if stored
    valorant_lb_regions = {"AP", "BR", "EU", "KR", "LATAM", "NA"}
    if region is not None:
        if not isinstance(region, str) or len(region.strip()) == 0:
            _log_call("meta-snapshots-list", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid region", field="region")
        region = region.strip()
        if game in {"LOL", "TFT"}:
            if region not in (lol_style_regions | global_regions):
                _log_call("meta-snapshots-list", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid region for product", field="region", product=game, allowed=sorted(list(lol_style_regions | global_regions)))
        elif game == "VALORANT":
            # Only restrict if requesting leaderboard-like snapshots; otherwise allow broader schema regions
            if snapshot_type == "VALORANT_LEADERBOARD" and region not in valorant_lb_regions:
                _log_call("meta-snapshots-list", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid region for VALORANT leaderboard", field="region", allowed=sorted(list(valorant_lb_regions)))
        else:
            # ESPORTS snapshots generally should not be region-scoped; allow but must still be known if provided
            if region not in (lol_style_regions | global_regions | valorant_lb_regions):
                _log_call("meta-snapshots-list", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid region", field="region")

    def _minlen_str(v, field):
        if v is None:
            return None
        if not isinstance(v, str) or len(v.strip()) == 0:
            return _err("VALIDATION_ERROR", f"Invalid {field}", field=field)
        return v.strip()

    for fld in ["champion_external_key", "tft_champion_external_key", "tft_item_external_key", "valorant_map_external_key", "esports_league_short_name", "source_patch", "game_mode"]:
        val = locals()[fld]
        if val is not None:
            if not isinstance(val, str) or len(val.strip()) == 0:
                _log_call("meta-snapshots-list", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Invalid {fld}", field=fld)
            locals()[fld] = val.strip()

    ef_lte = _parse_dt(effective_from_lte, "effective_from_lte") if effective_from_lte is not None else None
    if effective_from_lte is not None and ef_lte is None:
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid effective_from_lte datetime", field="effective_from_lte")
    et_gte = _parse_dt(effective_to_gte, "effective_to_gte") if effective_to_gte is not None else None
    if effective_to_gte is not None and et_gte is None:
        _log_call("meta-snapshots-list", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid effective_to_gte datetime", field="effective_to_gte")

    # Tool snapshot_type/game are "vendor" enums; datastore uses slightly different enums.
    # Map tool request to datastore snapshot_type and game.
    game_map = {"ESPORTS": "ESPORTS_LOL"}
    db_game = game_map.get(game, game)

    snapshot_type_map = {
        "LOL_CHAMPION_ANALYSIS": "LOL_CHAMPION_ANALYSIS",
        "LOL_CHAMPION_POSITIONS": "LOL_CHAMPION_POSITIONS_DATA",
        "LOL_CHAMPION_LEADERBOARD": "LOL_CHAMPION_LEADERBOARD",
        "TFT_META": "TFT_META_TREND_DECK_LIST",
        "TFT_BUILDS": "TFT_CHAMPION_ITEM_BUILD",
        "TFT_LEADERBOARD": "TFT_RECOMMEND_CHAMPION_FOR_ITEM",  # best-effort mapping
        "VALORANT_LEADERBOARD": "VALORANT_LEADERBOARD",
        "VALORANT_AGENT_META": "VALORANT_META_CHARACTERS",
        "ESPORTS_STANDINGS": "ESPORTS_LOL_TEAM_STANDINGS",
        "ESPORTS_SCHEDULE": "ESPORTS_LOL_SCHEDULES",
    }
    db_snapshot_type = snapshot_type_map.get(snapshot_type)

    # format normalization: for LoL positions tool rule default is 'csv' if omitted (and should reflect lookup key)
    if snapshot_type == "LOL_CHAMPION_POSITIONS" and format is None:
        format = "csv"

    # Catalog key validation: if provided, must exist and be active (business rule).
    catalog = _load("game_catalog.json")
    if not isinstance(catalog, list):
        catalog = []
    def _require_active_catalog(entity_game, entity_type, ext_key, field):
        if ext_key is None:
            return None
        for r in catalog:
            if r.get("game") == entity_game and r.get("entity_type") == entity_type and r.get("external_key") == ext_key and r.get("status") == "active":
                return None
        return _err("NOT_FOUND", "Unknown or inactive catalog external key", field=field, external_key=ext_key, game=entity_game, entity_type=entity_type)

    if champion_external_key is not None:
        e = _require_active_catalog("LOL", "LOL_CHAMPION", champion_external_key, "champion_external_key")
        if e:
            _log_call("meta-snapshots-list", "NOT_FOUND")
            return e
    if tft_champion_external_key is not None:
        e = _require_active_catalog("TFT", "TFT_CHAMPION", tft_champion_external_key, "tft_champion_external_key")
        if e:
            _log_call("meta-snapshots-list", "NOT_FOUND")
            return e
    if tft_item_external_key is not None:
        e = _require_active_catalog("TFT", "TFT_ITEM", tft_item_external_key, "tft_item_external_key")
        if e:
            _log_call("meta-snapshots-list", "NOT_FOUND")
            return e
    if valorant_map_external_key is not None:
        e = _require_active_catalog("VALORANT", "VALORANT_MAP", valorant_map_external_key, "valorant_map_external_key")
        if e:
            _log_call("meta-snapshots-list", "NOT_FOUND")
            return e

    # Ambient auth: no explicit token param; only refuse if no store combination can serve product.
    # Since no auth collections are provided for OP.GG in this schema, treat access as allowed.
    # (Never deny a well-formed request solely due to missing explicit auth param.)

    snaps = _load("meta_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    def _dt_or_min(v):
        if not isinstance(v, str):
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        d = _parse_dt(v, "dt")
        if d is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d

    # Apply filters
    out = []
    for r in snaps:
        if r.get("game") != db_game:
            continue
        if r.get("snapshot_type") != db_snapshot_type:
            continue
        if status is not None and r.get("status") != status:
            continue
        if region is not None and r.get("region") != region:
            continue
        if lang is not None and r.get("lang") != lang:
            continue
        if game_mode is not None and r.get("game_mode") != game_mode:
            continue
        if position is not None and r.get("position") != position:
            continue
        if champion_external_key is not None and r.get("champion_external_key") != champion_external_key:
            continue
        if tft_champion_external_key is not None and r.get("tft_champion_external_key") != tft_champion_external_key:
            continue
        if tft_item_external_key is not None and r.get("tft_item_external_key") != tft_item_external_key:
            continue
        if valorant_map_external_key is not None and r.get("valorant_map_external_key") != valorant_map_external_key:
            continue
        if esports_league_short_name is not None and r.get("esports_league_short_name") != esports_league_short_name:
            continue
        if format is not None and r.get("format") != format:
            continue
        if source_patch is not None and r.get("source_patch") != source_patch:
            continue

        eff_from = _dt_or_min(r.get("effective_from"))
        if ef_lte is not None:
            _ef = ef_lte
            if _ef.tzinfo is None:
                _ef = _ef.replace(tzinfo=datetime.timezone.utc)
            if eff_from > _ef:
                continue

        if et_gte is not None:
            _et = et_gte
            if _et.tzinfo is None:
                _et = _et.replace(tzinfo=datetime.timezone.utc)
            eff_to_raw = r.get("effective_to")
            if eff_to_raw is None:
                pass
            else:
                eff_to = _dt_or_min(eff_to_raw)
                if eff_to < _et:
                    continue

        out.append(r)

    # sort by effective_from desc then created_at desc
    out.sort(key=lambda x: (_dt_or_min(x.get("effective_from")), _dt_or_min(x.get("created_at"))), reverse=True)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = out[start:end]
    has_more = end < total

    # Return headers (no payload)
    headers = []
    for r in page_rows:
        hdr = dict(r)
        if "payload" in hdr:
            hdr.pop("payload", None)
        headers.append(hdr)

    resp = {
        "data": headers,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
        }
    }
    _log_call("meta-snapshots-list", "OK", detail={"returned": len(headers)})
    return resp

def renewal_jobs_create(product, region, game_name, tag_line, requested_by=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0449000" if __import__("os").path.isdir("./environment_mix/0449000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    # --- audit/rate-limit dynamics (best-effort based on request_logs.json if present) ---
    def _log_call(endpoint, status_code, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_code,
            "timestamp": _iso(_now),
            "latency_ms": latency_ms,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        # Stricter limit for renewals: 30/minute global
        window_s = 60
        limit = 30
        cutoff = _now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs[-5000:]:
            if r.get("endpoint") != "renewal-jobs-create":
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                ss = ts.strip()
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit, window_seconds=window_s)
        return None

    rl = _rate_limit_check()
    if rl:
        _log_call("renewal-jobs-create", "RATE_LIMIT")
        return rl

    # --- validation ---
    allowed_product = {"LOL", "TFT", "VALORANT"}
    if not isinstance(product, str) or product not in allowed_product:
        _log_call("renewal-jobs-create", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid product", field="product", allowed=sorted(list(allowed_product)))

    if not isinstance(region, str) or len(region.strip()) == 0:
        _log_call("renewal-jobs-create", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid region", field="region")
    region = region.strip()

    # Region enums are product-specific (business rule). Renewal jobs schema is LOL-only.
    lol_style_regions = {"KR", "BR", "EUNE", "EUW", "LAN", "LAS", "NA", "OCE", "RU", "TR", "JP", "PH", "SG", "TH", "TW", "VN", "ME", "SEA"}
    valorant_regions = {"AP", "BR", "EU", "KR", "LATAM", "NA"}

    if product in {"LOL", "TFT"}:
        if region not in lol_style_regions:
            _log_call("renewal-jobs-create", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid region for product", field="region", product=product, allowed=sorted(list(lol_style_regions)))
    else:  # VALORANT
        if region not in valorant_regions and region not in lol_style_regions:
            # allow broader if store uses LoL-style, but still validate known enums
            _log_call("renewal-jobs-create", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid region for VALORANT", field="region", allowed=sorted(list(valorant_regions | lol_style_regions)))

    if not isinstance(game_name, str) or len(game_name.strip()) == 0:
        _log_call("renewal-jobs-create", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid game_name", field="game_name")
    if not isinstance(tag_line, str) or len(tag_line.strip()) == 0:
        _log_call("renewal-jobs-create", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid tag_line", field="tag_line")
    game_name = game_name.strip()
    tag_line = tag_line.strip()

    if requested_by is not None and (not isinstance(requested_by, str) or len(requested_by.strip()) == 0):
        _log_call("renewal-jobs-create", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid requested_by", field="requested_by")
    if requested_by is not None:
        requested_by = requested_by.strip()

    # Ambient auth: no explicit credential parameter, and schema provides no token tables.
    # Therefore treat caller as authorized for allowed operations; do not spuriously deny.

    # Renewal job creation only supported by schema for LOL.
    if product != "LOL":
        _log_call("renewal-jobs-create", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Renewal jobs are only supported for LOL in this service datastore", field="product", supported=["LOL"])

    # normalized riot id canonicalization
    def _norm_riot_id(gn, tl):
        gn2 = re.sub(r"\s+", " ", gn.strip()).lower()
        tl2 = re.sub(r"\s+", " ", tl.strip()).lower()
        return f"{gn2}#{tl2}"
    normalized_riot_id = _norm_riot_id(game_name, tag_line)

    jobs = _load("renewal_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    players = _load("players.json")
    if not isinstance(players, list):
        players = []
    matches = _load("player_matches.json")
    if not isinstance(matches, list):
        matches = []

    # Create a queued job row (always insert per rule)
    job_id = "rjob_" + uuid.uuid4().hex
    now_iso = _iso(_now)
    job = {
        "id": job_id,
        "product": "LOL",
        "region": region,
        "game_name": game_name,
        "tag_line": tag_line,
        "normalized_riot_id": normalized_riot_id,
        "player_id": None,
        "requested_by": requested_by,
        "status": "queued",
        "attempt_count": 0,
        "last_error": None,
        "enqueued_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)

    # Dispatch execution inline (simulate execution as per business rule).
    # Transition queued -> running -> succeeded.
    job["status"] = "running"
    job["attempt_count"] = int(job.get("attempt_count") or 0) + 1
    job["started_at"] = now_iso
    job["updated_at"] = now_iso

    # Upsert player row (LOL, region, normalized_riot_id)
    player = None
    for p in players:
        if p.get("product") == "LOL" and p.get("region") == region and p.get("normalized_riot_id") == normalized_riot_id:
            player = p
            break

    if player is None:
        player_id = "plr_" + uuid.uuid4().hex
        player = {
            "id": player_id,
            "product": "LOL",
            "game_name": game_name,
            "tag_line": tag_line,
            "normalized_riot_id": normalized_riot_id,
            "region": region,
            "puuid": None,
            "profile_payload": {
                "renewed_via": "renewal-jobs-create",
                "riot_id": {"game_name": game_name, "tag_line": tag_line},
                "region": region,
                "updated_at": now_iso,
            },
            "last_renewed_at": now_iso,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        players.append(player)
    else:
        # update cache payload minimally; do not fabricate more than necessary
        player["game_name"] = game_name
        player["tag_line"] = tag_line
        player["last_renewed_at"] = now_iso
        if player.get("status") == "disabled":
            # legal transition disabled -> active
            player["status"] = "active"
        elif player.get("status") == "not_found":
            # legal transition not_found -> active
            player["status"] = "active"
        elif player.get("status") not in {"active", "not_found", "disabled"}:
            player["status"] = "active"
        pp = player.get("profile_payload")
        if not isinstance(pp, dict):
            pp = {}
        pp.update({"renewed_via": "renewal-jobs-create", "updated_at": now_iso, "region": region})
        player["profile_payload"] = pp
        player["updated_at"] = now_iso

    job["player_id"] = player["id"]

    # Upsert a small set of recent player_matches (best-effort; ensure played_at <= ingested_at)
    # Create 5 synthetic cached summaries only if they don't already exist for that player (idempotent-ish).
    # External match ids are deterministic per player+day so repeated renewal doesn't create duplicates.
    ingested_at = _now
    played_base = _now - datetime.timedelta(hours=1)
    created = 0

    existing_ext = set()
    for m in matches:
        if m.get("player_id") == player["id"]:
            em = m.get("external_match_id")
            if isinstance(em, str):
                existing_ext.add(em)

    for i in range(5):
        played_at = played_base - datetime.timedelta(minutes=30 * i)
        ext_id = f"LOL_{player['id']}_{played_at.strftime('%Y%m%d%H%M')}"
        if ext_id in existing_ext:
            continue
        m_id = "pm_" + uuid.uuid4().hex
        m_row = {
            "id": m_id,
            "player_id": player["id"],
            "product": "LOL",
            "region": region,
            "external_match_id": ext_id,
            "played_at": _iso(played_at),
            "queue_or_mode": "RANKED",
            "summary_payload": {
                "source": "cache_refresh",
                "result": "unknown",
                "kda": None,
            },
            "ingested_at": _iso(ingested_at),
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        matches.append(m_row)
        created += 1

    # Mark job succeeded
    job["status"] = "succeeded"
    job["finished_at"] = now_iso
    job["updated_at"] = now_iso

    _save("players.json", players)
    _save("player_matches.json", matches)
    _save("renewal_jobs.json", jobs)

    resp = {"data": job, "meta": {"matches_upserted": created, "player_id": player["id"]}}
    _log_call("renewal-jobs-create", "OK", detail={"job_id": job_id, "matches_upserted": created})
    return resp
